#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Given a non‐empty Vec<i8>, returns a Vec<i8> of the same length
    /// where each element is:
    ///   - -1 if the input element is < 0
    ///   -  0 if the input element == 0
    ///   -  1 if the input element > 0
    #[verifier(publish)]
    fn sign(x: Vec<i8>) -> (result: Vec<i8>)
        requires
            x.len() > 0
        ensures
            // The output has the same length as the input
            result.len() == x.len()
        ensures
            // Each output element classifies the sign of the corresponding input
            forall |j: usize|
                j < x.len() ==> 
                result[j] ==
                    if x[j] < 0 {
                        -1
                    } else if x[j] == 0 {
                        0
                    } else {
                        1
                    }
    {
        let n = x.len();
        // build an empty Vec and reserve space
        let mut result: Vec<i8> = Vec::new();
        result.reserve(n);

        // index into x, also the current length of result
        let mut i: usize = 0;
        while i < n
            invariant
                // ‣ i never exceeds n
                i <= n,
            invariant
                // ‣ we've built exactly i elements so far
                result.len() == i,
            invariant
                // ‣ for all j<i, result[j] is the correct sign of x[j]
                forall |j: usize|
                    j < i ==>
                    result[j] ==
                        if x[j] < 0 {
                            -1
                        } else if x[j] == 0 {
                            0
                        } else {
                            1
                        },
            decreases
                n - i
        {
            // read x[i] and classify
            let xi = x[i];
            let si: i8 = if xi < 0 {
                -1
            } else if xi == 0 {
                0
            } else {
                1
            };
            result.push(si);
            i += 1;
        }

        result
    }

}